/* ChartPulse — Global Styles */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-primary: #0f0f0f;
  --bg-secondary: #1a1a2e;
  --bg-card: #16162a;
  --bg-elevated: #1e1e3a;
  --bg-input: #252542;
  --border: #2a2a4a;
  --border-light: #333360;
  --text-primary: #e8e8f0;
  --text-secondary: #9090b0;
  --text-muted: #606080;
  --accent-blue: #2962FF;
  --accent-blue-hover: #1e50d0;
  --accent-teal: #00bcd4;
  --gain: #26a69a;
  --gain-bg: rgba(38,166,154,0.12);
  --loss: #ef5350;
  --loss-bg: rgba(239,83,80,0.12);
  --gold: #f5a623;
  --platinum: #b0b0c8;
  --font: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

a { color: var(--accent-blue); text-decoration: none; transition: color .2s; }
a:hover { color: var(--accent-teal); }

/* Layout */
.container { max-width: 1400px; margin: 0 auto; padding: 0 24px; }
.container-wide { max-width: 1600px; margin: 0 auto; padding: 0 24px; }

/* =================== NAVBAR =================== */
.navbar {
  position: sticky; top: 0; z-index: 100;
  background: rgba(15,15,15,0.92); backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  padding: 0 24px; height: 56px;
  display: flex; align-items: center;
}
.navbar .container-wide { display: flex; align-items: center; width: 100%; }
.nav-logo { font-size: 20px; font-weight: 800; color: var(--text-primary); display: flex; align-items: center; gap: 8px; }
.nav-logo .logo-icon { width: 28px; height: 28px; background: var(--accent-blue); border-radius: 6px; display: flex; align-items: center; justify-content: center; font-size: 14px; color: #fff; font-weight: 800; }
.nav-links { display: flex; gap: 4px; margin-left: 32px; }
.nav-links a {
  color: var(--text-secondary); padding: 8px 14px; border-radius: 6px;
  font-size: 13px; font-weight: 500; transition: all .2s;
}
.nav-links a:hover, .nav-links a.active { color: var(--text-primary); background: var(--bg-elevated); }
.nav-right { margin-left: auto; display: flex; align-items: center; gap: 12px; }
.nav-search {
  background: var(--bg-input); border: 1px solid var(--border); border-radius: 8px;
  padding: 7px 14px; color: var(--text-primary); font-size: 13px; width: 240px;
  font-family: var(--font); outline: none; transition: border-color .2s;
}
.nav-search:focus { border-color: var(--accent-blue); }
.nav-search::placeholder { color: var(--text-muted); }
.btn-primary {
  background: var(--accent-blue); color: #fff; border: none; border-radius: 8px;
  padding: 8px 18px; font-size: 13px; font-weight: 600; cursor: pointer;
  font-family: var(--font); transition: background .2s;
}
.btn-primary:hover { background: var(--accent-blue-hover); }
.btn-outline {
  background: transparent; color: var(--text-primary); border: 1px solid var(--border);
  border-radius: 8px; padding: 7px 16px; font-size: 13px; font-weight: 500;
  cursor: pointer; font-family: var(--font); transition: all .2s;
}
.btn-outline:hover { border-color: var(--accent-blue); color: var(--accent-blue); }

/* =================== TABS =================== */
.tabs { display: flex; gap: 2px; background: var(--bg-secondary); border-radius: 8px; padding: 3px; }
.tab-btn {
  padding: 7px 16px; border-radius: 6px; border: none; background: transparent;
  color: var(--text-secondary); font-size: 13px; font-weight: 500; cursor: pointer;
  font-family: var(--font); transition: all .2s; white-space: nowrap;
}
.tab-btn:hover { color: var(--text-primary); }
.tab-btn.active { background: var(--accent-blue); color: #fff; }
.tab-content { display: none; }
.tab-content.active { display: block; }

/* =================== CARDS =================== */
.card {
  background: var(--bg-card); border: 1px solid var(--border); border-radius: 12px;
  padding: 20px; transition: border-color .2s;
}
.card:hover { border-color: var(--border-light); }

/* =================== BADGES =================== */
.badge-gain {
  background: var(--gain-bg); color: var(--gain); padding: 2px 8px;
  border-radius: 4px; font-size: 12px; font-weight: 600;
}
.badge-loss {
  background: var(--loss-bg); color: var(--loss); padding: 2px 8px;
  border-radius: 4px; font-size: 12px; font-weight: 600;
}
.badge-neutral {
  background: rgba(144,144,176,0.12); color: var(--text-secondary); padding: 2px 8px;
  border-radius: 4px; font-size: 12px; font-weight: 600;
}

/* =================== SECTION HEADERS =================== */
.section-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 20px; }
.section-title { font-size: 20px; font-weight: 700; }
.section-subtitle { color: var(--text-secondary); font-size: 14px; }

/* =================== MARKET BAR =================== */
.market-bar {
  display: flex; gap: 0; overflow-x: auto; background: var(--bg-secondary);
  border-bottom: 1px solid var(--border); padding: 0 24px;
  scrollbar-width: none;
}
.market-bar::-webkit-scrollbar { display: none; }
.market-bar-item {
  display: flex; align-items: center; gap: 10px; padding: 10px 20px;
  border-right: 1px solid var(--border); white-space: nowrap; min-width: fit-content;
}
.market-bar-item:last-child { border-right: none; }
.market-bar-name { font-size: 12px; color: var(--text-secondary); font-weight: 500; }
.market-bar-price { font-size: 13px; font-weight: 600; color: var(--text-primary); }
.market-bar-change { font-size: 12px; font-weight: 600; }

/* =================== TABLES =================== */
.data-table { width: 100%; border-collapse: collapse; }
.data-table th {
  text-align: left; padding: 10px 12px; font-size: 11px; font-weight: 600;
  color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.5px;
  border-bottom: 1px solid var(--border);
}
.data-table td {
  padding: 10px 12px; font-size: 13px; border-bottom: 1px solid rgba(42,42,74,0.5);
}
.data-table tr:hover td { background: rgba(42,42,74,0.3); }
.data-table .text-right { text-align: right; }

/* =================== SPARKLINE =================== */
.sparkline { width: 80px; height: 32px; }

/* =================== GRID LAYOUTS =================== */
.grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }

/* =================== FOOTER =================== */
.footer {
  background: var(--bg-secondary); border-top: 1px solid var(--border);
  padding: 48px 24px 24px; margin-top: 60px;
}
.footer-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 24px; max-width: 1400px; margin: 0 auto; }
.footer-col h4 { font-size: 13px; font-weight: 700; margin-bottom: 14px; color: var(--text-primary); }
.footer-col a { display: block; color: var(--text-secondary); font-size: 13px; margin-bottom: 8px; }
.footer-col a:hover { color: var(--text-primary); }
.footer-bottom {
  max-width: 1400px; margin: 32px auto 0; padding-top: 24px;
  border-top: 1px solid var(--border);
  display: flex; justify-content: space-between; align-items: center;
  font-size: 12px; color: var(--text-muted);
}

/* =================== TEXT UTILITIES =================== */
.text-gain { color: var(--gain); }
.text-loss { color: var(--loss); }
.text-muted { color: var(--text-muted); }
.text-secondary { color: var(--text-secondary); }
.font-mono { font-family: 'SF Mono', 'Fira Code', monospace; }
.font-bold { font-weight: 700; }
.text-sm { font-size: 13px; }
.text-xs { font-size: 11px; }
.text-lg { font-size: 18px; }
.text-xl { font-size: 24px; }
.text-center { text-align: center; }
.text-right { text-align: right; }
.mt-1 { margin-top: 8px; }
.mt-2 { margin-top: 16px; }
.mt-3 { margin-top: 24px; }
.mt-4 { margin-top: 32px; }
.mb-1 { margin-bottom: 8px; }
.mb-2 { margin-bottom: 16px; }
.mb-3 { margin-bottom: 24px; }
.mb-4 { margin-bottom: 32px; }
.gap-1 { gap: 8px; }
.gap-2 { gap: 16px; }
.flex { display: flex; }
.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.flex-1 { flex: 1; }
.flex-wrap { flex-wrap: wrap; }

/* =================== RESPONSIVE =================== */
@media (max-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .grid-3 { grid-template-columns: 1fr 1fr; }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 768px) {
  .grid-2, .grid-3, .grid-4 { grid-template-columns: 1fr; }
  .nav-links { display: none; }
  .nav-search { width: 160px; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .container, .container-wide { padding: 0 16px; }
  .market-bar { padding: 0 16px; }
}
@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; gap: 12px; }
}

