// Draw candlestick chart
function drawCandlestick(canvas) {
  const rect = canvas.parentElement.getBoundingClientRect();
  const dpr = window.devicePixelRatio || 1;
  canvas.width = rect.width * dpr;
  canvas.height = rect.height * dpr;
  canvas.style.width = rect.width + 'px';
  canvas.style.height = rect.height + 'px';
  const ctx = canvas.getContext('2d');
  ctx.scale(dpr, dpr);
  const w = rect.width, h = rect.height;

  ctx.fillStyle = '#0f0f0f';
  ctx.fillRect(0, 0, w, h);

  // Grid
  ctx.strokeStyle = 'rgba(42,42,74,0.3)';
  ctx.lineWidth = 0.5;
  for (let i = 1; i < 6; i++) {
    const y = (h / 6) * i;
    ctx.beginPath(); ctx.moveTo(60, y); ctx.lineTo(w - 60, y); ctx.stroke();
  }
  for (let i = 1; i < 10; i++) {
    const x = 60 + ((w - 120) / 10) * i;
    ctx.beginPath(); ctx.moveTo(x, 20); ctx.lineTo(x, h - 30); ctx.stroke();
  }

  // Generate candle data
  const numCandles = 60;
  const candleW = (w - 140) / numCandles;
  const gap = candleW * 0.2;
  const bodyW = candleW - gap;
  let price = 268;
  const candles = [];
  for (let i = 0; i < numCandles; i++) {
    const open = price;
    const change = (Math.random() - 0.48) * 6;
    const close = open + change;
    const high = Math.max(open, close) + Math.random() * 3;
    const low = Math.min(open, close) - Math.random() * 3;
    candles.push({ open, close, high, low });
    price = close;
  }

  const allPrices = candles.flatMap(c => [c.high, c.low]);
  const minP = Math.min(...allPrices) - 2;
  const maxP = Math.max(...allPrices) + 2;
  const priceH = h - 50;

  function yPos(p) { return 20 + (1 - (p - minP) / (maxP - minP)) * priceH; }

  // Price labels
  ctx.fillStyle = '#606080';
  ctx.font = '10px Inter, sans-serif';
  ctx.textAlign = 'right';
  for (let i = 0; i <= 5; i++) {
    const p = minP + (maxP - minP) * (i / 5);
    ctx.fillText(p.toFixed(2), w - 8, yPos(p) + 3);
  }

  // Volume bars
  candles.forEach((c, i) => {
    const x = 70 + i * candleW;
    const vol = 20 + Math.random() * 30;
    const volH = vol * 0.8;
    ctx.fillStyle = c.close >= c.open ? 'rgba(38,166,154,0.2)' : 'rgba(239,83,80,0.2)';
    ctx.fillRect(x, h - 30 - volH, bodyW, volH);
  });

  // Candles
  candles.forEach((c, i) => {
    const x = 70 + i * candleW;
    const centerX = x + bodyW / 2;
    const isGreen = c.close >= c.open;
    const color = isGreen ? '#26a69a' : '#ef5350';

    // Wick
    ctx.strokeStyle = color;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(centerX, yPos(c.high));
    ctx.lineTo(centerX, yPos(c.low));
    ctx.stroke();

    // Body
    const top = yPos(Math.max(c.open, c.close));
    const bottom = yPos(Math.min(c.open, c.close));
    const bodyH = Math.max(bottom - top, 1);
    ctx.fillStyle = color;
    ctx.fillRect(x, top, bodyW, bodyH);
  });

  // Current price line
  const lastPrice = candles[candles.length - 1].close;
  const lineY = yPos(lastPrice);
  ctx.setLineDash([4, 4]);
  ctx.strokeStyle = '#ef5350';
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(70, lineY); ctx.lineTo(w - 60, lineY); ctx.stroke();
  ctx.setLineDash([]);

  ctx.fillStyle = '#ef5350';
  ctx.fillRect(w - 60, lineY - 10, 52, 20);
  ctx.fillStyle = '#fff';
  ctx.font = '10px Inter, sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText(lastPrice.toFixed(2), w - 34, lineY + 4);

  // MA overlay
  ctx.strokeStyle = 'rgba(41,98,255,0.6)';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  for (let i = 5; i < candles.length; i++) {
    let sum = 0;
    for (let j = i - 5; j <= i; j++) sum += candles[j].close;
    const ma = sum / 6;
    const x = 70 + i * candleW + bodyW / 2;
    if (i === 5) ctx.moveTo(x, yPos(ma));
    else ctx.lineTo(x, yPos(ma));
  }
  ctx.stroke();
}

window.addEventListener('load', () => drawCandlestick(document.getElementById('candlestickChart')));
window.addEventListener('resize', () => drawCandlestick(document.getElementById('candlestickChart')));
</script>
