<script>
// Market nav scroll
document.querySelectorAll('.mnav-btn').forEach(btn => {
  btn.addEventListener('click', () => {
    document.querySelectorAll('.mnav-btn').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    const target = document.getElementById(btn.dataset.scroll);
    if (target) target.scrollIntoView({ behavior: 'smooth' });
  });
});

// Session tabs for stock movers
document.querySelectorAll('.session-tab').forEach(tab => {
  tab.addEventListener('click', () => {
    document.querySelectorAll('.session-tab').forEach(t => t.classList.remove('active'));
    tab.classList.add('active');
    document.querySelectorAll('[id^="session-"]').forEach(c => c.classList.remove('active'));
    document.getElementById('session-' + tab.dataset.session).classList.add('active');
  });
});

// Chart type controls
document.querySelectorAll('.cc-btn').forEach(btn => {
  btn.addEventListener('click', () => {
    const group = btn.parentElement;
    const siblings = Array.from(group.children).filter(c => c.classList.contains('cc-btn'));
    const idx = siblings.indexOf(btn);
    const sep = Array.from(group.children).findIndex(c => !c.classList.contains('cc-btn'));
    if (sep > 0) {
      if (idx < sep) siblings.slice(0, sep).forEach(b => b.classList.remove('active'));
      else siblings.slice(sep).forEach(b => b.classList.remove('active'));
    }
    btn.classList.add('active');
  });
});

// Yield curve
function drawYieldCurve() {
  const canvas = document.getElementById('yieldCurve');
  if (!canvas) return;
  const rect = canvas.parentElement.getBoundingClientRect();
  const dpr = window.devicePixelRatio || 1;
  canvas.width = (rect.width - 40) * dpr;
  canvas.height = 200 * dpr;
  canvas.style.width = (rect.width - 40) + 'px';
  canvas.style.height = '200px';
  const ctx = canvas.getContext('2d');
  ctx.scale(dpr, dpr);
  const w = rect.width - 40, h = 200;

  const data = [
    { label: '1Y', yield: 3.682 },
    { label: '2Y', yield: 3.767 },
    { label: '5Y', yield: 3.903 },
    { label: '10Y', yield: 4.295 },
    { label: '20Y', yield: 4.900 },
    { label: '30Y', yield: 4.919 },
  ];

  const minY = 3.5, maxY = 5.1;
  const padL = 50, padR = 30, padT = 20, padB = 30;
  const chartW = w - padL - padR;
  const chartH = h - padT - padB;

  // Grid
  ctx.strokeStyle = 'rgba(42,42,74,0.3)';
  ctx.lineWidth = 0.5;
  for (let i = 0; i <= 4; i++) {
    const y = padT + (chartH / 4) * i;
    ctx.beginPath(); ctx.moveTo(padL, y); ctx.lineTo(w - padR, y); ctx.stroke();
    const val = maxY - ((maxY - minY) / 4) * i;
    ctx.fillStyle = '#606080';
    ctx.font = '10px Inter, sans-serif';
    ctx.textAlign = 'right';
    ctx.fillText(val.toFixed(2) + '%', padL - 8, y + 3);
  }

  // Curve
  const gradient = ctx.createLinearGradient(padL, 0, w - padR, 0);
  gradient.addColorStop(0, '#2962FF');
  gradient.addColorStop(1, '#00bcd4');

  ctx.strokeStyle = gradient;
  ctx.lineWidth = 3;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.beginPath();
  data.forEach((d, i) => {
    const x = padL + (chartW / (data.length - 1)) * i;
    const y = padT + (1 - (d.yield - minY) / (maxY - minY)) * chartH;
    if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  });
  ctx.stroke();

  // Fill under curve
  const gradFill = ctx.createLinearGradient(0, padT, 0, h - padB);
  gradFill.addColorStop(0, 'rgba(41,98,255,0.15)');
  gradFill.addColorStop(1, 'rgba(41,98,255,0)');
  ctx.lineTo(padL + chartW, h - padB);
  ctx.lineTo(padL, h - padB);
  ctx.closePath();
  ctx.fillStyle = gradFill;
  ctx.fill();

  // Points and labels
  data.forEach((d, i) => {
    const x = padL + (chartW / (data.length - 1)) * i;
    const y = padT + (1 - (d.yield - minY) / (maxY - minY)) * chartH;
    ctx.beginPath();
    ctx.arc(x, y, 4, 0, Math.PI * 2);
    ctx.fillStyle = '#2962FF';
    ctx.fill();
    ctx.strokeStyle = '#0f0f0f';
    ctx.lineWidth = 2;
    ctx.stroke();

    ctx.fillStyle = '#e8e8f0';
    ctx.font = '11px Inter, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(d.yield.toFixed(3) + '%', x, y - 12);

    ctx.fillStyle = '#606080';
    ctx.font = '10px Inter, sans-serif';
    ctx.fillText(d.label, x, h - 8);
  });
}
window.addEventListener('load', drawYieldCurve);
window.addEventListener('resize', drawYieldCurve);
</script>
